+
+    public VetsView(VetRepository vetRepository) {
+        this.vetRepository = vetRepository;
+        setSizeFull();
+        setPadding(true);
+        setSpacing(true);
+
+        H1 heading = new H1("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+
+        Grid<Vet> grid = new Grid<>(Vet.class, false);
+        grid.setSizeFull();
+        grid.addColumn(Vet::firstName).setHeader("First name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                        ? "none"
+                        : vet.specialties().stream().collect(Collectors.joining(", ")))
+                .setHeader("Specialties").setKey("specialties");
+        grid.setDataProvider(DataProvider.fromFilteringCallbacks(
+                query -> this.vetRepository.findPage(query.getOffset(), query.getLimit()),
+                query -> this.vetRepository.count()));
+
+        add(heading, grid);
+        expand(grid);
+    }
